// Turn a free-text weekly roster into structured entries (or accept entries as given).
// Text format:
//   Week 2026-06-01
//   Agent Alpha: Sun-Thu 09:00-16:00, Fri-Sat off
const b = $input.item.json.body || $input.item.json;
const DAYS = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'];
const rawText = String(b.rawText || '');
let weekStart = b.weekStart || '';
let entries = Array.isArray(b.entries) ? b.entries : [];
const unparsed = [];

const addDays = (iso, n) => {
  const d = new Date(`${iso}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() + n);
  return d.toISOString().slice(0, 10);
};

if (entries.length === 0 && rawText) {
  const parsed = [];
  for (const line of rawText.split(/\r?\n/)) {
    const t = line.trim();
    if (!t) continue;
    const wk = t.match(/^week\s+(\d{4}-\d{2}-\d{2})$/i);
    if (wk) {
      weekStart = wk[1];
      continue;
    }
    const m = t.match(/^([^:]+):\s*(.+)$/);
    if (!m || !weekStart) {
      unparsed.push(t);
      continue;
    }
    for (const part of m[2].split(',')) {
      const p = part.trim().toLowerCase();
      const mm = p.match(/^([a-z]{3})(?:\s*-\s*([a-z]{3}))?\s+(?:(off)|(\d{2}:\d{2})\s*-\s*(\d{2}:\d{2}))$/);
      const from = mm ? DAYS.indexOf(mm[1]) : -1;
      const to = mm ? (mm[2] ? DAYS.indexOf(mm[2]) : from) : -1;
      if (!mm || from < 0 || to < from) {
        unparsed.push(`${m[1].trim()}: ${part.trim()}`);
        continue;
      }
      for (let d = from; d <= to; d += 1) {
        parsed.push(
          mm[3]
            ? { agent: m[1].trim(), date: addDays(weekStart, d), off: true }
            : { agent: m[1].trim(), date: addDays(weekStart, d), start: mm[4], end: mm[5], off: false },
        );
      }
    }
  }
  entries = parsed;
}

if (entries.length === 0) throw new Error('no schedule entries found');

return { json: { weekStart, entries, rawText, unparsed } };
